import numpy as np


class Matrix:
    def __init__(self, values):
        self._values = values

    @classmethod
    def zeros(cls, rows, columns):
        return cls([[0.0] * columns] * rows)

    @classmethod
    def from_ndarray(cls, values):
        return cls(values.astype(int))

    def to_ndarray(self):
        return np.asarray(self._values)

    def set(self, row, column, value):
        self._values[row][column] = value

    def transpose(self):
        return Matrix(np.asarray(self._values).T)

    def sum(self, axis=None):
        return np.asarray(self._values).sum()

    def copy(self):
        return Matrix(self._values)
